/* MISRA C:2004 Rule 14.7 and C:2012/2023 Rule 15.5 deviation: early
   returns keep validation failures next to their bounds/resource checks.
   C:2012/2023 Rule 17.7 deviation: synchronization cleanup and calls whose
   arguments are validated constants may discard status; initialized ThreadX
   objects and application-thread context are public API preconditions. */

/* Original implementation of the pinned up-spec MQTT mapping and basic types.
   Only the transport mapping is implemented; payload serialization is opaque. */
#include "nxd_uprotocol.h"
#include <string.h>

/* Bounded output writer shared by strings and MQTT property fields. */
typedef struct UP_WRITER_STRUCT
{
    UCHAR *data;
    UINT size;
    UINT used;
    UINT failed;
} UP_WRITER;

/* Return size when the string has no terminating NUL within its storage. */
static UINT up_length(const CHAR *text, UINT size)
{
UINT n = 0;
    while (n < size && text[n] != '\0')
    {
        n++;
    }
    return(n);
}

/* Append bytes without truncating a successful result. */
static VOID up_bytes(UP_WRITER *writer, const VOID *data, UINT length)
{
    if (writer -> failed || length > writer -> size - writer -> used)
    {
        writer -> failed = 1;
        return;
    }
    if (length)
    {
        memcpy(writer -> data + writer -> used, data, length);
        writer -> used += length;
    }
}

/* Encode an integer as network bytes or decimal/hexadecimal ASCII. */
static VOID up_number(UP_WRITER *writer, uint32_t value, UINT base, UINT width)
{
UCHAR bytes[10];
UINT n = 0;
UINT i;
static const UCHAR digits[] = "0123456789ABCDEF";

    if (base == 256u)
    {
        for (i = 0; i < width; i++)
        {
            bytes[i] = (UCHAR)(value >> (8u * (width - i - 1u)));
        }
        up_bytes(writer, bytes, width);
    }
    else
    {
        do
        {
            bytes[n++] = digits[value % base];
            value /= base;
        } while (value);
        while (n)
        {
            up_bytes(writer, &bytes[--n], 1);
        }
    }
}

/* Parse a bounded integer, rejecting overflow and empty input. */
static UINT up_integer(const UCHAR *data, UINT length, UINT base, uint32_t maximum, uint32_t *value)
{
UINT i;
UINT digit;
    *value = 0;
    if (!length)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    for (i = 0; i < length; i++)
    {
        if (data[i] >= '0' && data[i] <= '9')
        {
            digit = data[i] - '0';
        }
        else if (data[i] >= 'A' && data[i] <= 'F')
        {
            digit = data[i] - 'A' + 10u;
        }
        else if (data[i] >= 'a' && data[i] <= 'f')
        {
            digit = data[i] - 'a' + 10u;
        }
        else
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        if (digit >= base || *value > (maximum - digit) / base || digit > maximum)
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        *value = *value * base + digit;
    }
    return(NXD_UPROTOCOL_OK);
}

/* Validate the decimal IPv4 tail of an IPv6 literal. */
static UINT up_ipv4(const CHAR *text, UINT length)
{
UINT i = 0;
UINT part;
UINT start;
uint32_t value;
    for (part = 0; part < 4; part++)
    {
        start = i;
        while (i < length && text[i] >= '0' && text[i] <= '9')
        {
            i++;
        }
        if (i == start || i - start > 3u || (i - start > 1u && text[start] == '0') ||
            up_integer((const UCHAR *)text + start, i - start, 10, 255, &value)) { return(0); }
        if (part < 3 && (i >= length || text[i++] != '.'))
        {
            return(0);
        }
    }
    return(i == length);
}

/* Validate URI authorities, including RFC 3986 IPv6 and IPvFuture literals. */
static UINT up_authority(const CHAR *authority, UINT wildcard)
{
UINT n = up_length(authority, NXD_UPROTOCOL_AUTHORITY_MAX + 1u);
UINT i;
UINT start;
UINT groups = 0;
UINT compressed = 0;
uint32_t value;
CHAR c;
    if (n > NXD_UPROTOCOL_AUTHORITY_MAX)
    {
        return(0);
    }
    if (wildcard && n == 1 && authority[0] == '*')
    {
        return(1);
    }
    if (n && authority[0] == '[')
    {
        if (n < 4 || authority[n - 1] != ']')
        {
            return(0);
        }
        if (authority[1] == 'v')
        {
            i = 2;
            while (i < n - 1 && ((authority[i] >= '0' && authority[i] <= '9') ||
                   (authority[i] >= 'a' && authority[i] <= 'f'))) { i++; }
            if (i == 2 || i >= n - 2 || authority[i++] != '.')
            {
                return(0);
            }
            for (; i < n - 1; i++)
            {
                c = authority[i];
                if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ||
                    c == '-' || c == '.' || c == '_' || c == '~' || c == ':' ||
                    c == '!' || c == '$' || c == '&' || c == '\'' || c == '(' ||
                    c == ')' || c == '*' || c == '+' || c == ',' || c == ';' || c == '=')) { return(0); }
            }
            return(1);
        }
        i = 1;
        if (authority[i] == ':')
        {
            if (authority[i + 1] != ':')
            {
                return(0);
            }
            compressed = 1;
            i += 2;
        }
        while (i < n - 1)
        {
            start = i;
            while (i < n - 1 && authority[i] != ':')
            {
                i++;
            }
            if (memchr(authority + start, '.', i - start) != NX_NULL)
            {
                if (i != n - 1 || !up_ipv4(authority + start, i - start))
                {
                    return(0);
                }
                groups += 2;
            }
            else
            {
                if (i - start > 4u || up_integer((const UCHAR *)authority + start, i - start, 16, 65535, &value))
                {
                    return(0);
                }
                groups++;
            }
            if (i < n - 1)
            {
                i++;
                if (i < n - 1 && authority[i] == ':')
                {
                    if (compressed)
                    {
                        return(0);
                    }
                    compressed = 1;
                    i++;
                }
                else if (i == n - 1)
                {
                    return(0);
                }
            }
        }
        return(compressed ? groups < 8u : groups == 8u);
    }
    for (i = 0; i < n; i++)
    {
        c = authority[i];
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '.' || c == '_' || c == '~'))
        {
            return(0);
        }
    }
    return(1);
}

/* Validate field widths and optionally allow URI filter wildcards. */
static UINT up_uri_valid(const NXD_UPROTOCOL_URI *uri, UINT filter)
{
    if (uri == NX_NULL || uri -> version > 255u || uri -> resource > 65535u || !up_authority(uri -> authority, filter))
    {
        return(0);
    }
    return(filter || ((uri -> ue_id & 65535u) != 65535u && (uri -> ue_id >> 16) != 65535u &&
                      uri -> version != 255u && uri -> resource != 65535u));
}

/* Serialize a UUri using the canonical up: scheme and uppercase hexadecimal. */
UINT nxd_uprotocol_uri_format(const NXD_UPROTOCOL_URI *uri, CHAR *text, UINT size)
{
UP_WRITER writer = {(UCHAR *)text, size, 0, 0};
    if (text == NX_NULL || !up_uri_valid(uri, 1))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    up_bytes(&writer, "up:", 3);
    if (uri -> authority[0])
    {
        up_bytes(&writer, "//", 2);
        up_bytes(&writer, uri -> authority, up_length(uri -> authority, sizeof(uri -> authority)));
    }
    up_bytes(&writer, "/", 1);
    up_number(&writer, uri -> ue_id, 16, 0);
    up_bytes(&writer, "/", 1);
    up_number(&writer, uri -> version, 16, 0);
    up_bytes(&writer, "/", 1);
    up_number(&writer, uri -> resource, 16, 0);
    up_bytes(&writer, "", 1);
    return(writer.failed ? NXD_UPROTOCOL_RESOURCE_EXHAUSTED : NXD_UPROTOCOL_OK);
}

/* Parse absolute or relative URI forms, rejecting excess fields and suffixes. */
UINT nxd_uprotocol_uri_parse(const CHAR *text, NXD_UPROTOCOL_URI *uri)
{
UINT at = 0;
UINT start;
UINT part;
UINT length;
uint32_t number;
uint32_t values[3];
    if (text == NX_NULL || uri == NX_NULL)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    length = up_length(text, NXD_UPROTOCOL_URI_SIZE);
    if (length == NXD_UPROTOCOL_URI_SIZE)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    memset(uri, 0, sizeof(*uri));
    if (length >= 3 && memcmp(text, "up:", 3) == 0)
    {
        at = 3;
    }
    if (at + 1 < length && text[at] == '/' && text[at + 1] == '/')
    {
        at += 2;
        start = at;
        while (at < length && text[at] != '/')
        {
            at++;
        }
        if (at - start > NXD_UPROTOCOL_AUTHORITY_MAX)
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        memcpy(uri -> authority, text + start, at - start);
    }
    for (part = 0; part < 3; part++)
    {
        if (at >= length || text[at++] != '/')
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        start = at;
        while (at < length && text[at] != '/')
        {
            at++;
        }
        if (at - start > (part == 0 ? 8u : (part == 1 ? 2u : 4u)) ||
            up_integer((const UCHAR *)text + start, at - start, 16,
                       part == 0 ? UINT32_MAX : (part == 1 ? 255u : 65535u), &number))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        values[part] = number;
    }
    uri -> ue_id = values[0];
    uri -> version = (UINT)values[1];
    uri -> resource = (UINT)values[2];
    return(at == length && up_uri_valid(uri, 1) ? NXD_UPROTOCOL_OK : NXD_UPROTOCOL_INVALID_ARGUMENT);
}

/* Match the independent type, instance, version, resource and authority patterns. */
UINT nxd_uprotocol_uri_matches(const NXD_UPROTOCOL_URI *pattern, const NXD_UPROTOCOL_URI *candidate)
{
    if (!up_uri_valid(pattern, 1) || !up_uri_valid(candidate, 0))
    {
        return(0);
    }
    return((strcmp(pattern -> authority, "*") == 0 || strcmp(pattern -> authority, candidate -> authority) == 0) &&
           ((pattern -> ue_id & 65535u) == 65535u || (pattern -> ue_id & 65535u) == (candidate -> ue_id & 65535u)) &&
           ((pattern -> ue_id >> 16) == 65535u || (pattern -> ue_id >> 16) == (candidate -> ue_id >> 16)) &&
           (pattern -> version == 255u || pattern -> version == candidate -> version) &&
           (pattern -> resource == 65535u || pattern -> resource == candidate -> resource));
}

/* Check RFC 9562 version and variant bits. */
static UINT up_uuid_valid(const NXD_UPROTOCOL_UUID *uuid)
{
    return((uuid -> bytes[6] & 0xF0u) == 0x70u && (uuid -> bytes[8] & 0xC0u) == 0x80u);
}

/* Generate UUIDv7 from an application clock and fresh entropy. */
UINT nxd_uprotocol_uuid_create(NXD_UPROTOCOL_UUID *uuid, uint64_t milliseconds, const UCHAR random[10])
{
UINT i;
    if (uuid == NX_NULL || random == NX_NULL || milliseconds > UINT64_C(0xFFFFFFFFFFFF))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    for (i = 0; i < 6; i++)
    {
        uuid -> bytes[i] = (UCHAR)(milliseconds >> (40u - i * 8u));
    }
    memcpy(uuid -> bytes + 6, random, 10);
    uuid -> bytes[6] = (UCHAR)((uuid -> bytes[6] & 15u) | 0x70u);
    uuid -> bytes[8] = (UCHAR)((uuid -> bytes[8] & 63u) | 0x80u);
    return(NXD_UPROTOCOL_OK);
}

/* Serialize the UUID using lowercase RFC hex-and-dash representation. */
UINT nxd_uprotocol_uuid_format(const NXD_UPROTOCOL_UUID *uuid, CHAR *text, UINT size)
{
UINT i;
UINT at = 0;
static const CHAR digits[] = "0123456789abcdef";
    if (uuid == NX_NULL || text == NX_NULL || !up_uuid_valid(uuid))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    if (size < 37u)
    {
        return(NXD_UPROTOCOL_RESOURCE_EXHAUSTED);
    }
    for (i = 0; i < 16; i++)
    {
        if (i == 4 || i == 6 || i == 8 || i == 10)
        {
            text[at++] = '-';
        }
        text[at++] = digits[uuid -> bytes[i] >> 4];
        text[at++] = digits[uuid -> bytes[i] & 15u];
    }
    text[at] = '\0';
    return(NXD_UPROTOCOL_OK);
}

/* Parse a UUIDv7 string; accept either case for hexadecimal digits. */
UINT nxd_uprotocol_uuid_parse(const CHAR *text, NXD_UPROTOCOL_UUID *uuid)
{
UINT i;
UINT at = 0;
uint32_t value;
    if (text == NX_NULL || uuid == NX_NULL || up_length(text, 37) != 36)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    for (i = 0; i < 16; i++)
    {
        if (i == 4 || i == 6 || i == 8 || i == 10)
        {
            if (text[at++] != '-')
            {
                return(NXD_UPROTOCOL_INVALID_ARGUMENT);
            }
        }
        if (up_integer((const UCHAR *)text + at, 2, 16, 255u, &value))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        uuid -> bytes[i] = (UCHAR)value;
        at += 2;
    }
    return(up_uuid_valid(uuid) ? NXD_UPROTOCOL_OK : NXD_UPROTOCOL_INVALID_ARGUMENT);
}

/* An absent or zero TTL never expires. Equality at the deadline is still valid. */
UINT nxd_uprotocol_message_expired(const NXD_UPROTOCOL_MESSAGE *message, uint64_t now)
{
uint64_t created = 0;
UINT i;
    if (message == NX_NULL || !(message -> present & NXD_UPROTOCOL_HAS_TTL) || !message -> ttl)
    {
        return(0);
    }
    for (i = 0; i < 6; i++)
    {
        created = (created << 8) | message -> id.bytes[i];
    }
    return(now > created && now - created > message -> ttl);
}

/* Validate the base traceparent format and nonzero trace/span identifiers. */
static UINT up_trace_valid(const CHAR *text)
{
UINT n = up_length(text, NXD_UPROTOCOL_TRACE_SIZE);
UINT i;
UINT trace_nonzero = 0;
UINT span_nonzero = 0;
    if (!n)
    {
        return(1);
    }
    if (n < 55 || n == NXD_UPROTOCOL_TRACE_SIZE || text[2] != '-' || text[35] != '-' || text[52] != '-' ||
        (text[0] == 'f' && text[1] == 'f') || (text[0] == '0' && text[1] == '0' && n != 55)) { return(0); }
    for (i = 0; i < 55; i++)
    {
        if (i == 2 || i == 35 || i == 52)
        {
            continue;
        }
        if (!((text[i] >= '0' && text[i] <= '9') || (text[i] >= 'a' && text[i] <= 'f')))
        {
            return(0);
        }
        if (i >= 3 && i < 35 && text[i] != '0')
        {
            trace_nonzero = 1;
        }
        if (i >= 36 && i < 52 && text[i] != '0')
        {
            span_nonzero = 1;
        }
    }
    return(trace_nonzero && span_nonzero && (n == 55 || text[55] == '-'));
}

/* Validate common and message-type-specific attribute invariants. */
UINT nxd_uprotocol_message_validate(const NXD_UPROTOCOL_MESSAGE *m)
{
UINT has_sink;
    if (m == NX_NULL || !up_uuid_valid(&m -> id) || !up_uri_valid(&m -> source, 0) ||
        m -> priority > 7u || m -> payload_format > 8u || (m -> present & ~31u) ||
        (m -> payload == NX_NULL && m -> payload_length) || (!m -> payload_length && m -> payload_format) ||
        up_length(m -> token, sizeof(m -> token)) == sizeof(m -> token) || !up_trace_valid(m -> traceparent))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    has_sink = m -> present & NXD_UPROTOCOL_HAS_SINK;
    if (has_sink && !up_uri_valid(&m -> sink, 0))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    if ((m -> present & NXD_UPROTOCOL_HAS_REQID) && !up_uuid_valid(&m -> reqid))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    if ((m -> present & NXD_UPROTOCOL_HAS_STATUS) && (m -> commstatus > 16u || m -> type != NXD_UPROTOCOL_RESPONSE))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    if ((m -> present & NXD_UPROTOCOL_HAS_REQID) && m -> type != NXD_UPROTOCOL_RESPONSE)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    if (((m -> present & NXD_UPROTOCOL_HAS_PERMISSION) || m -> token[0]) && m -> type != NXD_UPROTOCOL_REQUEST)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    switch (m -> type)
    {
    case NXD_UPROTOCOL_PUBLISH:
        if (has_sink && (m -> sink.ue_id || m -> sink.version || m -> sink.resource || !m -> sink.authority[0]))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        return(m -> source.resource >= 0x8000u ? 0u : NXD_UPROTOCOL_INVALID_ARGUMENT);
    case NXD_UPROTOCOL_NOTIFICATION:
        return(has_sink && m -> sink.resource == 0 && m -> source.resource >= 0x8000u ? 0u : NXD_UPROTOCOL_INVALID_ARGUMENT);
    case NXD_UPROTOCOL_REQUEST:
        return(has_sink && m -> source.resource == 0 && m -> sink.resource > 0 && m -> sink.resource < 0x8000u &&
               m -> priority >= NXD_UPROTOCOL_CS4 && (m -> present & NXD_UPROTOCOL_HAS_TTL) && m -> ttl ? 0u : NXD_UPROTOCOL_INVALID_ARGUMENT);
    case NXD_UPROTOCOL_RESPONSE:
        return(has_sink && m -> sink.resource == 0 && m -> source.resource > 0 && m -> source.resource < 0x8000u &&
               m -> priority >= NXD_UPROTOCOL_CS4 && (m -> present & NXD_UPROTOCOL_HAS_REQID) &&
               (m -> present & NXD_UPROTOCOL_HAS_TTL) && m -> ttl ? 0u : NXD_UPROTOCOL_INVALID_ARGUMENT);
    default: return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
}

/* Append one URI's five MQTT topic segments, translating filter wildcards. */
static VOID up_topic_uri(UP_WRITER *writer, const NXD_UPROTOCOL_URI *uri, const CHAR *authority, UINT filter, UINT mode)
{
uint32_t values[4];
UINT i;
const CHAR *name = uri -> authority[0] ? uri -> authority : authority;
    if (filter && strcmp(name, "*") == 0)
    {
        name = "+";
    }
    up_bytes(writer, name, up_length(name, NXD_UPROTOCOL_AUTHORITY_MAX + 1));
    if (mode == NXD_UPROTOCOL_D2D)
    {
        return;
    }
    values[0] = uri -> ue_id & 65535u;
    values[1] = uri -> ue_id >> 16;
    values[2] = uri -> version;
    values[3] = uri -> resource;
    for (i = 0; i < 4; i++)
    {
        up_bytes(writer, "/", 1);
        if (filter && values[i] == (i == 2 ? 255u : 65535u))
        {
            up_bytes(writer, "+", 1);
        }
        else
        {
            up_number(writer, values[i], 16, 0);
        }
    }
}

/* Construct E2E/D2D topics or subscription filters. D2D needs a sink authority. */
UINT nxd_uprotocol_topic(const NXD_UPROTOCOL_URI *source, const NXD_UPROTOCOL_URI *sink,
                         const CHAR *authority, UINT mode, UINT filter, CHAR *topic, UINT size)
{
UP_WRITER writer = {(UCHAR *)topic, size, 0, 0};
    if (topic == NX_NULL || authority == NX_NULL || !authority[0] || !up_authority(authority, 0) ||
        mode > 1u || !up_uri_valid(source, filter) || (sink != NX_NULL && !up_uri_valid(sink, filter)) ||
        (mode == NXD_UPROTOCOL_D2D && sink == NX_NULL)) { return(NXD_UPROTOCOL_INVALID_ARGUMENT); }
    up_topic_uri(&writer, source, authority, filter, mode);
    if (sink != NX_NULL)
    {
        up_bytes(&writer, "/", 1);
        up_topic_uri(&writer, sink, authority, filter, mode);
    }
    up_bytes(&writer, "", 1);
    return(writer.failed ? NXD_UPROTOCOL_RESOURCE_EXHAUSTED : NXD_UPROTOCOL_OK);
}

/* Encode an MQTT length-prefixed string and a User Property pair. */
static VOID up_string(UP_WRITER *writer, const CHAR *text, UINT length)
{
    up_number(writer, length, 256, 2);
    up_bytes(writer, text, length);
}
static VOID up_property(UP_WRITER *writer, const CHAR *key, const CHAR *value)
{
    up_number(writer, 38, 256, 1);
    up_string(writer, key, (UINT)strlen(key));
    up_string(writer, value, (UINT)strlen(value));
}
static VOID up_decimal_property(UP_WRITER *writer, const CHAR *key, uint32_t value)
{
UCHAR buffer[11];
UP_WRITER number = {buffer, sizeof(buffer), 0, 0};
    up_number(&number, value, 10, 0);
    up_bytes(&number, "", 1);
    up_property(writer, key, (const CHAR *)buffer);
}

/* Encode exactly the MQTT 5 properties required by populated UAttributes. */
UINT nxd_uprotocol_encode(const NXD_UPROTOCOL_MESSAGE *m, UCHAR *properties, UINT size, UINT *length)
{
UP_WRITER writer = {properties, size, 0, 0};
CHAR text[NXD_UPROTOCOL_URI_SIZE];
static const CHAR *const types[] = {"", "up-pub.v1", "up-req.v1", "up-res.v1", "up-not.v1"};
    if (properties == NX_NULL || length == NX_NULL || nxd_uprotocol_message_validate(m))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    up_property(&writer, "uP", "1");
    nxd_uprotocol_uuid_format(&m -> id, text, sizeof(text));
    up_property(&writer, "1", text);
    up_property(&writer, "2", types[m -> type]);
    nxd_uprotocol_uri_format(&m -> source, text, sizeof(text));
    up_property(&writer, "3", text);
    if (m -> present & NXD_UPROTOCOL_HAS_SINK)
    {
        nxd_uprotocol_uri_format(&m -> sink, text, sizeof(text));
        up_property(&writer, "4", text);
    }
    if (m -> priority)
    {
        text[0] = 'C';
        text[1] = 'S';
        text[2] = (CHAR)('0' + m -> priority - 1u);
        text[3] = '\0';
        up_property(&writer, "5", text);
    }
    if (m -> present & NXD_UPROTOCOL_HAS_TTL)
    {
        up_number(&writer, 2, 256, 1);
        up_number(&writer, m -> ttl / 1000u + (m -> ttl % 1000u != 0u), 256, 4);
        if (m -> ttl % 1000u)
        {
            up_decimal_property(&writer, "6", m -> ttl);
        }
    }
    if (m -> present & NXD_UPROTOCOL_HAS_PERMISSION)
    {
        up_decimal_property(&writer, "7", m -> permission_level);
    }
    if (m -> present & NXD_UPROTOCOL_HAS_STATUS)
    {
        up_decimal_property(&writer, "8", m -> commstatus);
    }
    if (m -> present & NXD_UPROTOCOL_HAS_REQID)
    {
        up_number(&writer, 9, 256, 1);
        up_number(&writer, 16, 256, 2);
        up_bytes(&writer, m -> reqid.bytes, 16);
    }
    if (m -> token[0])
    {
        up_property(&writer, "10", m -> token);
    }
    if (m -> traceparent[0])
    {
        up_property(&writer, "11", m -> traceparent);
    }
    if (m -> payload_format)
    {
        text[0] = (CHAR)('0' + m -> payload_format);
        text[1] = '\0';
        up_number(&writer, 3, 256, 1);
        up_string(&writer, text, 1);
    }
    *length = writer.used;
    if (writer.failed)
    {
        return(NXD_UPROTOCOL_RESOURCE_EXHAUSTED);
    }
    return(_nxd_mqtt5_properties_validate(properties, writer.used, 3) ? NXD_UPROTOCOL_INVALID_ARGUMENT : NXD_UPROTOCOL_OK);
}

/* Read a string view from an already MQTT-validated property block. */
static UINT up_read_string(const UCHAR *data, UINT end, UINT *at, const UCHAR **value, UINT *length)
{
    if (*at > end || end - *at < 2)
    {
        return(0);
    }
    *length = ((UINT)data[*at] << 8) | data[*at + 1]; *at += 2;
    if (*length > end - *at)
    {
        return(0);
    }
    *value = data + *at; *at += *length;
    return(1);
}

/* Decode known uProtocol properties, reject duplicate metadata, preserve extras
   defined by the pinned schema. Payload is supplied separately by the transport. */
UINT nxd_uprotocol_decode(const UCHAR *data, UINT length, NXD_UPROTOCOL_MESSAGE *m)
{
UINT at = 0;
UINT id;
UINT key_length;
UINT value_length;
UINT field;
UINT seen = 0;
UINT i;
uint32_t number;
uint32_t expiry = 0;
UINT has_expiry = 0;
const UCHAR *key;
const UCHAR *value;
CHAR text[NXD_UPROTOCOL_URI_SIZE];
static const CHAR *const types[] = {"", "up-pub.v1", "up-req.v1", "up-res.v1", "up-not.v1"};
    if (m == NX_NULL || (data == NX_NULL && length) || _nxd_mqtt5_properties_validate(data, length, 3))
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    memset(m, 0, sizeof(*m));
    while (at < length)
    {
        id = data[at++];
        if (id == 2)
        {
            expiry = 0;
            for (i = 0; i < 4; i++)
            {
                expiry = (expiry << 8) | data[at++];
            }
            has_expiry = 1;
            continue;
        }
        if (id == 1)
        {
            at++;
            continue;
        }
        if (!up_read_string(data, length, &at, &value, &value_length))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        if (id == 9)
        {
            if (value_length != 16)
            {
                return(NXD_UPROTOCOL_INVALID_ARGUMENT);
            }
            memcpy(m -> reqid.bytes, value, 16);
            m -> present |= NXD_UPROTOCOL_HAS_REQID;
            continue;
        }
        if (id == 3)
        {
            if (up_integer(value, value_length, 10, 8, &number))
            {
                return(NXD_UPROTOCOL_INVALID_ARGUMENT);
            }
            m -> payload_format = (UINT)number;
            continue;
        }
        if (id != 38)
        {
            continue;
        }
        key = value;
        key_length = value_length;
        if (!up_read_string(data, length, &at, &value, &value_length))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        if (key_length == 2 && memcmp(key, "uP", 2) == 0)
        {
            field = 0;
        }
        else if (up_integer(key, key_length, 10, 11, &number) || number == 0)
        {
            continue;
        }
        else
        {
            field = (UINT)number;
        }
        if (field == 9 || (seen & (1u << field)))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        seen |= 1u << field;
        if (field == 10 || field == 11)
        {
            CHAR *target = field == 10 ? m -> token : m -> traceparent;
            UINT capacity = field == 10 ? sizeof(m -> token) : sizeof(m -> traceparent);
            if (value_length >= capacity)
            {
                return(NXD_UPROTOCOL_RESOURCE_EXHAUSTED);
            }
            memcpy(target, value, value_length);
            target[value_length] = '\0';
            continue;
        }
        if (value_length >= sizeof(text))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        memcpy(text, value, value_length);
        text[value_length] = '\0';
        switch (field)
        {
        case 0: if (strcmp(text, "1"))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        break;
        case 1: if (nxd_uprotocol_uuid_parse(text, &m -> id))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        break;
        case 2:
            for (i = 1; i <= 4; i++)
            {
                if (strcmp(text, types[i]) == 0)
                {
                    m -> type = i;
                }
            }
            if (!m -> type)
            {
                return(NXD_UPROTOCOL_INVALID_ARGUMENT);
            }
            break;
        case 3: if (nxd_uprotocol_uri_parse(text, &m -> source))
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        break;
        case 4:
            if (nxd_uprotocol_uri_parse(text, &m -> sink))
            {
                return(NXD_UPROTOCOL_INVALID_ARGUMENT);
            }
            m -> present |= NXD_UPROTOCOL_HAS_SINK;
            break;
        case 5:
            if (value_length != 3 || text[0] != 'C' || text[1] != 'S' || text[2] < '0' || text[2] > '6')
            {
                return(NXD_UPROTOCOL_INVALID_ARGUMENT);
            }
            m -> priority = (UINT)(text[2] - '0') + 1u;
            break;
        default:
            if (up_integer(value, value_length, 10, UINT32_MAX, &number))
            {
                return(NXD_UPROTOCOL_INVALID_ARGUMENT);
            }
            if (field == 6)
            {
                m -> ttl = number;
                m -> present |= NXD_UPROTOCOL_HAS_TTL;
            }
            if (field == 7)
            {
                m -> permission_level = number;
                m -> present |= NXD_UPROTOCOL_HAS_PERMISSION;
            }
            if (field == 8)
            {
                m -> commstatus = (UINT)number;
                m -> present |= NXD_UPROTOCOL_HAS_STATUS;
            }
            break;
        }
    }
    if ((seen & 15u) != 15u)
    {
        return(NXD_UPROTOCOL_INVALID_ARGUMENT);
    }
    if (seen & (1u << 6))
    {
        /* Broker expiry may decrease while queued; the original millisecond TTL remains authoritative. */
        if (!has_expiry || m -> ttl % 1000u == 0 || expiry > m -> ttl / 1000u + 1u)
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
    }
    else if (has_expiry)
    {
        if (expiry > UINT32_MAX / 1000u)
        {
            return(NXD_UPROTOCOL_INVALID_ARGUMENT);
        }
        m -> ttl = expiry * 1000u;
        m -> present |= NXD_UPROTOCOL_HAS_TTL;
    }
    return(NXD_UPROTOCOL_OK);
}
